import { parseBoardCode } from './boardCode';
import type { BoardDescription } from './boardCode';
import { generateDeck } from './deck';
import { SELECTION } from './selection';
import type { Selection } from './selection';

export const MAX_MOVES = 999999;
export const MAX_ELAPSED_MS = 359999999;

export interface Board extends BoardDescription {
  readonly deck: readonly number[];
}

export interface GameState {
  readonly board: Board;
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState {
  const description = parseBoardCode(boardCode);
  if (!description) throw new Error('Invalid board code.');
  const board = Object.freeze({ ...description, deck: generateDeck(description) });
  return {
    board, matched: [], selection: { kind: SELECTION.closed },
    moves: 0, elapsedMs: 0, started: false,
  };
}

export function pairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

export function formatTime(elapsedMs: number): string {
  const seconds = Math.floor(elapsedMs / 1000);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}
import { MISMATCH_MS, SELECTION } from './selection';
import { MAX_MOVES } from './state';
import type { GameState } from './state';

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.board.deck.length) return state;
  if (state.matched.includes(index)) return state;
  const selection = state.selection;
  switch (selection.kind) {
    case SELECTION.mismatch:
      return state;
    case SELECTION.closed:
      return { ...state, started: true, selection: { kind: SELECTION.one, index } };
    case SELECTION.one: {
      if (selection.index === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.board.deck[selection.index] === state.board.deck[index]) {
        return {
          ...state, moves, matched: [...state.matched, selection.index, index],
          selection: { kind: SELECTION.closed },
        };
      }
      return {
        ...state, moves,
        selection: {
          kind: SELECTION.mismatch, first: selection.index, second: index,
          remainingMs: MISMATCH_MS,
        },
      };
    }
  }
}
import { SELECTION } from './selection';
import { isWon, MAX_ELAPSED_MS } from './state';
import type { GameState } from './state';

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) {
    return state;
  }
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  const selection = state.selection;
  switch (selection.kind) {
    case SELECTION.closed:
    case SELECTION.one:
      return elapsedMs === state.elapsedMs ? state : { ...state, elapsedMs };
    case SELECTION.mismatch: {
      const remainingMs = selection.remainingMs - milliseconds;
      return {
        ...state, elapsedMs,
        selection: remainingMs <= 0
          ? { kind: SELECTION.closed }
          : { ...selection, remainingMs },
      };
    }
  }
}
