import { describeFace } from './faces.ts';
import { FaceShape } from './FaceShape.tsx';

export interface FaceProps {
  face: number;
}

export function Face({ face }: FaceProps) {
  const identity = describeFace(face);
  const outlined = identity.fill === 'outline';
  return <svg className="card-face" viewBox="0 0 100 100" aria-hidden="true" focusable="false">
    <g fill={outlined ? 'none' : identity.color} stroke={outlined ? identity.color : 'none'}
      strokeWidth={outlined ? 5 : 0} strokeLinejoin="round">
      <FaceShape shape={identity.shape} />
    </g>
    <circle cx={identity.markerX} cy={identity.markerY} r="5" fill={identity.color}
      stroke="#111625" strokeWidth="3" />
  </svg>;
}
import type { Shape } from './faces.ts';

export interface FaceShapeProps {
  shape: Shape;
}

export function FaceShape({ shape }: FaceShapeProps) {
  switch (shape) {
    case 'circle': return <circle cx="50" cy="50" r="25" />;
    case 'square': return <rect x="25" y="25" width="50" height="50" />;
    case 'triangle': return <polygon points="50,25 75,75 25,75" />;
    case 'diamond': return <polygon points="50,25 75,50 50,75 25,50" />;
    case 'star': return <polygon points="50,25 57.35,39.89 73.78,42.27 61.89,53.86 64.69,70.23 50,62.5 35.31,70.23 38.11,53.86 26.22,42.27 42.65,39.89" />;
    case 'hexagon': return <polygon points="50,25 71.65,37.5 71.65,62.5 50,75 28.35,62.5 28.35,37.5" />;
    case 'plus': return <polygon points="40,25 60,25 60,40 75,40 75,60 60,60 60,75 40,75 40,60 25,60 25,40 40,40" />;
    case 'chevron': return <polygon points="25,25 50,45 75,25 75,50 50,75 25,50" />;
  }
}
export const SHAPES = ['circle', 'square', 'triangle', 'diamond', 'star', 'hexagon', 'plus', 'chevron'] as const;
export type Shape = (typeof SHAPES)[number];
export const MARKERS = ['top', 'top-right', 'right', 'bottom-right', 'bottom', 'bottom-left', 'left', 'top-left'] as const;
export const PALETTE = [
  { name: 'cyan', color: '#63E7FF' }, { name: 'magenta', color: '#FF71D6' },
  { name: 'green', color: '#8BEA7D' }, { name: 'yellow', color: '#FFE082' },
  { name: 'orange', color: '#FFB064' }, { name: 'violet', color: '#B49AFF' },
  { name: 'rose', color: '#FF8296' }, { name: 'ice', color: '#D9F3FF' },
] as const;
const DIAGONAL = 40 / Math.sqrt(2);
const MARKER_OFFSETS = [
  [0, -40], [DIAGONAL, -DIAGONAL], [40, 0], [DIAGONAL, DIAGONAL],
  [0, 40], [-DIAGONAL, DIAGONAL], [-40, 0], [-DIAGONAL, -DIAGONAL],
] as const;

export function describeFace(id: number) {
  if (!Number.isInteger(id) || id < 0 || id > 127) throw new Error('Invalid face.');
  const markerIndex = Math.floor(id / 8) % 8;
  const shape = SHAPES[id % 8];
  const palette = PALETTE[markerIndex];
  const marker = MARKERS[markerIndex];
  const offset = MARKER_OFFSETS[markerIndex];
  if (!shape || !palette || !marker || !offset) throw new Error('Invalid face.');
  const fill = id < 64 ? 'solid' : 'outline';
  return {
    shape, fill, color: palette.color, marker,
    markerX: 50 + offset[0], markerY: 50 + offset[1],
    name: `${palette.name} ${fill} ${shape}, marker ${marker}`,
  };
}
export function nextCard(index: number, size: number, key: string): number | null {
  const column = index % size;
  switch (key) {
    case 'ArrowLeft': return column > 0 ? index - 1 : index;
    case 'ArrowRight': return column < size - 1 ? index + 1 : index;
    case 'ArrowUp': return index >= size ? index - size : index;
    case 'ArrowDown': return index < size * (size - 1) ? index + size : index;
    default: return null;
  }
}

